// "SSC GK most asked topics" (/exams/ssc-gk-topics/ and /hi/exams/ssc-gk-topics/): a data page counted from
// every SSC previous-year paper we publish (src/data/gkInsights.mjs, generated by scripts/gen-gk-insights.mjs from the
// server's PYQ seed files). Every number on the page is computed from that file here, never typed in. Plain .mjs so
// scripts/prerender.mjs and the React page share one builder (same arrangement as examCalendar.mjs).
import { GK_INSIGHTS } from '../data/gkInsights.mjs';
import { EXAM_NAMES } from './examNames.mjs';
import { examHubPath, formatHubDate } from './examHubPath.mjs';
import { pyqPaperPathFor } from './pyqPath.mjs';

// The link other pages (hubs, papers lists) give to this page; the count comes from the data, so it never goes stale.
const TOTAL_TEXT = GK_INSIGHTS.total.toLocaleString('en-IN');
export const GK_INSIGHTS_LINK = {
  en: { href: '/exams/ssc-gk-topics/', label: `SSC GK most asked topics and answers: ${TOTAL_TEXT} past questions analysed` },
  hi: { href: '/hi/exams/ssc-gk-topics/', label: `SSC GK में सबसे ज़्यादा पूछे जाने वाले विषय और उत्तर: पिछले ${TOTAL_TEXT} प्रश्नों का विश्लेषण` },
};
export const GK_INSIGHTS_EXAMS = ['ssc_cgl', 'ssc_chsl', 'ssc_mts', 'ssc_gd'];
export const GK_INSIGHTS_PUBLISHED = '2026-10-22';

export function gkInsightsPath(lang) {
  return GK_INSIGHTS_LINK[lang === 'hi' ? 'hi' : 'en'].href;
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const TOPIC_NAMES = {
  STATIC_GK: ['Static GK (awards, sports, books, appointments, firsts)', 'स्टैटिक जीके (पुरस्कार, खेल, पुस्तकें, नियुक्तियाँ, प्रथम)'],
  ART_AND_CULTURE: ['Art and culture', 'कला और संस्कृति'],
  GENERAL_SCIENCE: ['General science', 'सामान्य विज्ञान'],
  INDIAN_POLITY: ['Polity and the Constitution', 'राजव्यवस्था और संविधान'],
  INDIAN_GEOGRAPHY: ['Indian geography', 'भारत का भूगोल'],
  INDIAN_ECONOMY: ['Indian economy', 'भारतीय अर्थव्यवस्था'],
  MODERN_INDIAN_HISTORY: ['Modern Indian history', 'आधुनिक भारतीय इतिहास'],
  ANCIENT_MEDIEVAL_HISTORY: ['Ancient and medieval history', 'प्राचीन और मध्यकालीन इतिहास'],
  WORLD_PHYSICAL_GEOGRAPHY: ['World and physical geography', 'विश्व एवं भौतिक भूगोल'],
  ENVIRONMENT_ECOLOGY: ['Environment and ecology', 'पर्यावरण और पारिस्थितिकी'],
  BANKING_AWARENESS: ['Banking and finance', 'बैंकिंग और वित्त'],
  COMPUTER_KNOWLEDGE: ['Computers', 'कंप्यूटर'],
};
const THEME_NAMES = {
  awards: ['Awards (Padma, Sangeet Natak Akademi, Bharat Ratna, sports awards)', 'पुरस्कार (पद्म, संगीत नाटक अकादमी, भारत रत्न, खेल पुरस्कार)'],
  dance: ['Classical and folk dances', 'शास्त्रीय और लोक नृत्य'],
  sports: ['Sports: players, trophies, terms', 'खेल: खिलाड़ी, ट्रॉफ़ी, शब्दावली'],
  books: ['Books and authors', 'पुस्तकें और लेखक'],
  music: ['Musical instruments and musicians', 'वाद्य यंत्र और संगीतकार'],
  festival: ['Festivals and fairs', 'त्योहार और मेले'],
  chemistry: ['Chemistry: elements, compounds, reactions', 'रसायन: तत्व, यौगिक, अभिक्रियाएँ'],
  schemes: ['Government schemes and missions', 'सरकारी योजनाएँ और मिशन'],
  appointments: ['Governors, chief ministers, appointments', 'राज्यपाल, मुख्यमंत्री, नियुक्तियाँ'],
  constitution: ['Constitution: articles, schedules, amendments', 'संविधान: अनुच्छेद, अनुसूचियाँ, संशोधन'],
  rivers: ['Rivers, dams and lakes', 'नदियाँ, बाँध और झीलें'],
  body: ['Human body, vitamins, diseases', 'मानव शरीर, विटामिन, रोग'],
};
const ANSWER_HI = {
  Kerala: 'केरल', Karnataka: 'कर्नाटक', Odisha: 'ओडिशा', 'Madhya Pradesh': 'मध्य प्रदेश', Bharatanatyam: 'भरतनाट्यम', Assam: 'असम',
  Maharashtra: 'महाराष्ट्र', 'Uttar Pradesh': 'उत्तर प्रदेश', Kathak: 'कथक', 'Tamil Nadu': 'तमिलनाडु', Gujarat: 'गुजरात', Rajasthan: 'राजस्थान',
  Sikkim: 'सिक्किम', 'Arunachal Pradesh': 'अरुणाचल प्रदेश', India: 'भारत',
};
const SHORT = { ssc_cgl: 'CGL', ssc_chsl: 'CHSL', ssc_mts: 'MTS', ssc_gd: 'GD' };

const D = GK_INSIGHTS;
const pct = (n, of) => (of ? (100 * n) / of : 0);
const fmtPct = (x) => `${x.toFixed(1)}%`;
const num = (n, lang) => Number(n).toLocaleString(lang === 'hi' ? 'hi-IN' : 'en-IN');
const topicName = (key, lang) => (TOPIC_NAMES[key] ?? [key, key])[lang === 'hi' ? 1 : 0];
const share = (topic) => pct(D.topics.find(([k]) => k === topic)?.[1] ?? 0, D.total);
const examShare = (examId, topic) => {
  const e = D.byExam[examId];
  return pct(e?.topics.find(([k]) => k === topic)?.[1] ?? 0, e?.total ?? 0);
};
const answerCount = (a) => D.topAnswers.find(([x]) => x === a)?.[1] ?? 0;
const STATES = new Set(['Kerala', 'Karnataka', 'Odisha', 'Madhya Pradesh', 'Assam', 'Maharashtra', 'Uttar Pradesh', 'Tamil Nadu', 'Gujarat', 'Rajasthan', 'Sikkim', 'Arunachal Pradesh', 'Andhra Pradesh', 'West Bengal', 'Bihar']);
/** The four states most often the correct answer, with their counts, in the page's language. */
const topStates = (lang) => D.topAnswers.filter(([a]) => STATES.has(a)).slice(0, 4)
  .map(([a, n]) => (lang === 'hi' ? `${ANSWER_HI[a] ?? a} ${n} बार` : `${a} ${n} times`)).join(', ');

const T = {
  en: {
    exams: 'All exams',
    switchLabel: 'हिंदी में पढ़ें',
    h1: `SSC GK most asked topics: ${num(D.total, 'en')} General Awareness questions from ${D.paperCount} papers`,
    lede: () =>
      `We counted every General Awareness question in the SSC previous-year papers we publish: SSC CGL Tier-I 2019 and 2024, CHSL Tier-I 2019 to 2021, MTS 2021, 2023 and 2024, and GD Constable 2022 (${D.papersByExam.ssc_gd} shifts). That is ${num(D.total, 'en')} questions, each with SSC's own answer key. This is where the General Awareness marks came from.`,
    findings: 'What the papers show',
    f: [
      () => `Static GK is the biggest share at ${fmtPct(share('STATIC_GK'))}: awards, sports, books and authors, appointments, firsts and important days.`,
      () => `Art and culture comes next at ${fmtPct(share('ART_AND_CULTURE'))}: classical and folk dances, festivals, musical instruments and musicians. Bharatanatyam alone is the correct answer ${answerCount('Bharatanatyam')} times, Kathak ${answerCount('Kathak')}.`,
      () => `"Which state?" is SSC's favourite answer. State names are the most frequent correct answers: ${topStates('en')}. Learn each state's dances, festivals, crafts and leaders together.`,
      () => `General science is ${fmtPct(share('GENERAL_SCIENCE'))}, polity ${fmtPct(share('INDIAN_POLITY'))}, Indian geography ${fmtPct(share('INDIAN_GEOGRAPHY'))} and economy ${fmtPct(share('INDIAN_ECONOMY'))}; history (modern, ancient and medieval) is ${fmtPct(share('MODERN_INDIAN_HISTORY') + share('ANCIENT_MEDIEVAL_HISTORY'))} together.`,
      () => `SSC almost never repeats a question word for word: only ${D.repeats.length} of ${num(D.total, 'en')} appear twice with the same wording and answer. Learn topics, not old answers.`,
      () => `The exams lean differently: CHSL gives ${fmtPct(examShare('ssc_chsl', 'STATIC_GK'))} of its General Awareness to static GK; GD Constable asks more economy (${fmtPct(examShare('ssc_gd', 'INDIAN_ECONOMY'))}) and polity (${fmtPct(examShare('ssc_gd', 'INDIAN_POLITY'))}); CGL more science (${fmtPct(examShare('ssc_cgl', 'GENERAL_SCIENCE'))}).`,
    ],
    topicsH: 'Most asked GK topics: share of each',
    topic: 'Topic', questions: 'Questions', shareCol: 'Share',
    byExamH: 'Topic shares by exam',
    byExamNote: (counts) => `Share of each exam's General Awareness questions. Questions counted: ${counts}.`,
    answersH: 'The answers SSC gives most often',
    answersNote: 'Correct answers that occur most often across all the papers (years, numbers and "all of the above" left out).',
    answer: 'Correct answer', times: 'Times',
    themesH: 'Themes inside the questions',
    themesNote: 'Counted from the words in each question, so one question can fall under two themes.',
    theme: 'Theme',
    repeatsH: (n) => `The ${n} questions SSC asked twice`,
    repeatsNote: 'Same wording and same answer, in different shifts or years.',
    askedIn: 'Asked in',
    methodH: 'How we counted',
    method: () =>
      `The papers are SSC's candidate response sheets, which print SSC's correct option for every question; we publish them as solved papers with a link to SSC's own notice. Topics are our own tags (one per question). The few General Awareness questions printed as images, and the rare question whose key we could not account for, are not in our files and so are not counted. GD Constable 2022 covers the shifts published so far, and its 2 February 2023 Shift 2 sheet prints this section in Hindi only, so it is not counted. Counted from the papers as published on ${formatHubDate(GK_INSIGHTS_PUBLISHED, 'en')}.`,
    practiceH: 'Practise with the real papers',
    papersOf: (name) => `${name}: solved previous-year papers`,
    ca: 'Daily current affairs from PIB, for static GK and awards',
    q: 'Free practice questions with answers',
  },
  hi: {
    exams: 'सभी परीक्षाएँ',
    switchLabel: 'Read in English',
    h1: `SSC GK में सबसे ज़्यादा पूछे जाने वाले विषय: ${D.paperCount} प्रश्नपत्रों के ${num(D.total, 'en')} सामान्य जागरूकता प्रश्न`,
    lede: () =>
      `हमने अपने प्रकाशित SSC पिछले वर्षों के प्रश्नपत्रों के हर सामान्य जागरूकता प्रश्न को गिना: SSC CGL टियर-I 2019 और 2024, CHSL टियर-I 2019 से 2021, MTS 2021, 2023 और 2024, और GD कांस्टेबल 2022 (${D.papersByExam.ssc_gd} पालियाँ)। कुल ${num(D.total, 'en')} प्रश्न, हर एक SSC की अपनी उत्तर कुंजी के साथ। सामान्य जागरूकता के अंक इन्हीं विषयों से आए।`,
    findings: 'प्रश्नपत्र क्या बताते हैं',
    f: [
      () => `सबसे बड़ा हिस्सा स्टैटिक जीके का है, ${fmtPct(share('STATIC_GK'))}: पुरस्कार, खेल, पुस्तकें और लेखक, नियुक्तियाँ, प्रथम और महत्वपूर्ण दिवस।`,
      () => `इसके बाद कला और संस्कृति, ${fmtPct(share('ART_AND_CULTURE'))}: शास्त्रीय और लोक नृत्य, त्योहार, वाद्य यंत्र और संगीतकार। अकेला भरतनाट्यम ${answerCount('Bharatanatyam')} बार सही उत्तर है, कथक ${answerCount('Kathak')} बार।`,
      () => `"कौन-सा राज्य?" SSC का सबसे प्रिय उत्तर है। सबसे ज़्यादा बार सही उत्तर राज्यों के नाम हैं: ${topStates('hi')}। हर राज्य के नृत्य, त्योहार, शिल्प और नेता साथ-साथ याद करें।`,
      () => `सामान्य विज्ञान ${fmtPct(share('GENERAL_SCIENCE'))}, राजव्यवस्था ${fmtPct(share('INDIAN_POLITY'))}, भारत का भूगोल ${fmtPct(share('INDIAN_GEOGRAPHY'))} और अर्थव्यवस्था ${fmtPct(share('INDIAN_ECONOMY'))} है; इतिहास (आधुनिक, प्राचीन और मध्यकालीन) मिलाकर ${fmtPct(share('MODERN_INDIAN_HISTORY') + share('ANCIENT_MEDIEVAL_HISTORY'))}।`,
      () => `SSC लगभग कभी भी कोई प्रश्न हूबहू नहीं दोहराता: ${num(D.total, 'en')} में से केवल ${D.repeats.length} प्रश्न उन्हीं शब्दों और उसी उत्तर के साथ दो बार आए। पुराने उत्तर नहीं, विषय याद करें।`,
      () => `परीक्षाओं का झुकाव अलग है: CHSL अपनी सामान्य जागरूकता का ${fmtPct(examShare('ssc_chsl', 'STATIC_GK'))} स्टैटिक जीके से पूछता है; GD कांस्टेबल अर्थव्यवस्था (${fmtPct(examShare('ssc_gd', 'INDIAN_ECONOMY'))}) और राजव्यवस्था (${fmtPct(examShare('ssc_gd', 'INDIAN_POLITY'))}) ज़्यादा पूछता है; CGL विज्ञान (${fmtPct(examShare('ssc_cgl', 'GENERAL_SCIENCE'))})।`,
    ],
    topicsH: 'सबसे ज़्यादा पूछे जाने वाले GK विषय: हर विषय का हिस्सा',
    topic: 'विषय', questions: 'प्रश्न', shareCol: 'हिस्सा',
    byExamH: 'परीक्षा-वार विषयों का हिस्सा',
    byExamNote: (counts) => `हर परीक्षा के सामान्य जागरूकता प्रश्नों में हिस्सा। गिने गए प्रश्न: ${counts}।`,
    answersH: 'SSC के सबसे ज़्यादा बार आने वाले सही उत्तर',
    answersNote: 'सभी प्रश्नपत्रों में सबसे ज़्यादा बार आने वाले सही उत्तर (वर्ष, संख्याएँ और "उपर्युक्त सभी" छोड़कर)।',
    answer: 'सही उत्तर', times: 'बार',
    themesH: 'प्रश्नों के भीतर के विषय-क्षेत्र',
    themesNote: 'हर प्रश्न के शब्दों से गिने गए, इसलिए एक प्रश्न दो विषय-क्षेत्रों में आ सकता है।',
    theme: 'विषय-क्षेत्र',
    repeatsH: (n) => `वे ${n} प्रश्न जो SSC ने दो बार पूछे`,
    repeatsNote: 'वही शब्द और वही उत्तर, अलग-अलग पालियों या वर्षों में। प्रश्न अंग्रेज़ी में हैं, जैसे प्रकाशित हुए।',
    askedIn: 'कहाँ पूछा गया',
    methodH: 'हमने कैसे गिना',
    method: () =>
      `ये प्रश्नपत्र SSC की अभ्यर्थी उत्तर-पुस्तिकाएँ (रिस्पॉन्स शीट) हैं, जिनमें हर प्रश्न का SSC का सही विकल्प छपा होता है; हम इन्हें SSC की अपनी सूचना के लिंक के साथ हल किए गए प्रश्नपत्रों के रूप में प्रकाशित करते हैं। विषय हमारे अपने टैग हैं (हर प्रश्न का एक)। चित्र के रूप में छपे कुछ सामान्य जागरूकता प्रश्न, और वे इक्का-दुक्का प्रश्न जिनकी कुंजी हम सही नहीं ठहरा सके, हमारी फ़ाइलों में नहीं हैं, इसलिए गिने नहीं गए। GD कांस्टेबल 2022 में अब तक प्रकाशित पालियाँ हैं, और उसकी 2 फ़रवरी 2023 की पाली 2 की शीट यह खंड केवल हिंदी में छापती है, इसलिए वह नहीं गिनी गई। ${formatHubDate(GK_INSIGHTS_PUBLISHED, 'hi')} को प्रकाशित प्रश्नपत्रों से गिना गया।`,
    practiceH: 'असली प्रश्नपत्रों से अभ्यास करें',
    papersOf: (name) => `${name}: हल किए गए पिछले वर्षों के प्रश्नपत्र`,
    ca: 'PIB से रोज़ के करेंट अफेयर्स, स्टैटिक जीके और पुरस्कारों के लिए',
    q: 'उत्तर सहित मुफ़्त अभ्यास प्रश्न',
  },
};

export function gkInsightsBody(lang = 'en') {
  const t = T[lang] ?? T.en;
  const L = lang === 'hi' ? 1 : 0;
  const other = gkInsightsPath(lang === 'hi' ? 'en' : 'hi');
  let html = `<div class="compare-top-row"><a href="${lang === 'hi' ? '/hi/exams/' : '/exams/'}" class="detail-back">&larr; ${t.exams}</a><a href="${other}" class="compare-lang-switch">${t.switchLabel}</a></div>`;
  html += `<h1>${esc(t.h1)}</h1><p class="compare-lede">${esc(t.lede())}</p>`;
  html += `<h2>${t.findings}</h2><ul class="gk-findings">${t.f.map((f) => `<li>${esc(f())}</li>`).join('')}</ul>`;

  html += `<h2>${t.topicsH}</h2><div class="hub-table-wrap"><table class="hub-table gk-table"><thead><tr><th>${t.topic}</th><th>${t.questions}</th><th>${t.shareCol}</th></tr></thead><tbody>`;
  for (const [key, n] of D.topics) html += `<tr><td>${esc(topicName(key, lang))}</td><td>${num(n, 'en')}</td><td>${fmtPct(pct(n, D.total))}</td></tr>`;
  html += `</tbody></table></div>`;

  const exams = GK_INSIGHTS_EXAMS.filter((e) => D.byExam[e]?.total > 0);
  const counts = exams.map((e) => `${SHORT[e]} ${num(D.byExam[e].total, 'en')}`).join(', ');
  html += `<h2>${t.byExamH}</h2><div class="hub-table-wrap"><table class="hub-table gk-table"><thead><tr><th>${t.topic}</th>${exams.map((e) => `<th>${SHORT[e]}</th>`).join('')}</tr></thead><tbody>`;
  for (const [key] of D.topics.slice(0, 8)) html += `<tr><td>${esc(topicName(key, lang))}</td>${exams.map((e) => `<td>${fmtPct(examShare(e, key))}</td>`).join('')}</tr>`;
  html += `</tbody></table></div><p class="exam-dir-note">${esc(t.byExamNote(counts))}</p>`;

  html += `<h2>${t.answersH}</h2><div class="hub-table-wrap"><table class="hub-table gk-table"><thead><tr><th>${t.answer}</th><th>${t.times}</th></tr></thead><tbody>`;
  for (const [a, n] of D.topAnswers) html += `<tr><td>${esc(L ? ANSWER_HI[a] ?? a : a)}</td><td>${n}</td></tr>`;
  html += `</tbody></table></div><p class="exam-dir-note">${esc(t.answersNote)}</p>`;

  html += `<h2>${t.themesH}</h2><div class="hub-table-wrap"><table class="hub-table gk-table"><thead><tr><th>${t.theme}</th><th>${t.questions}</th><th>${t.shareCol}</th></tr></thead><tbody>`;
  for (const [key, n] of D.themes) html += `<tr><td>${esc((THEME_NAMES[key] ?? [key, key])[L])}</td><td>${num(n, 'en')}</td><td>${fmtPct(pct(n, D.total))}</td></tr>`;
  html += `</tbody></table></div><p class="exam-dir-note">${esc(t.themesNote)}</p>`;

  html += `<h2>${esc(t.repeatsH(D.repeats.length))}</h2><p class="exam-dir-note">${esc(t.repeatsNote)}</p><ul class="hub-notices gk-repeats">`;
  for (const r of D.repeats) {
    const where = r.papers
      .map((p) => {
        const label = `${p.paper} · ${formatHubDate(p.date, lang)} · ${p.shift}`;
        const href = pyqPaperPathFor(p.examId, p);
        return href ? `<a href="${href}">${esc(label)}</a>` : esc(label);
      })
      .join('; ');
    html += `<li><span class="gk-q">${esc(r.text)} <strong>${esc(r.answer)}</strong></span><span>${t.askedIn}: ${where}</span></li>`;
  }
  html += `</ul>`;

  html += `<h2>${t.methodH}</h2><p>${esc(t.method())}</p>`;
  html += `<h2>${t.practiceH}</h2><ul class="compare-links">`;
  for (const e of exams) html += `<li><a href="${examHubPath(e, lang)}">${esc(t.papersOf(EXAM_NAMES[e] ?? e))}</a></li>`;
  html += `<li><a href="/app/current-affairs/">${t.ca}</a></li><li><a href="${lang === 'hi' ? '/hi/q/' : '/q/'}">${t.q}</a></li></ul>`;
  return html;
}

export function gkInsightsMeta(lang = 'en') {
  return lang === 'hi'
    ? {
        title: `SSC GK में सबसे ज़्यादा पूछे जाने वाले विषय और उत्तर: पिछले ${num(D.total, 'en')} प्रश्नों का विश्लेषण`,
        description: `SSC सामान्य जागरूकता में कौन-से विषय सबसे ज़्यादा पूछे जाते हैं: SSC CGL, CHSL, MTS और GD के ${D.paperCount} प्रश्नपत्रों के ${num(D.total, 'en')} प्रश्न गिने गए - स्टैटिक जीके ${fmtPct(share('STATIC_GK'))}, कला-संस्कृति ${fmtPct(share('ART_AND_CULTURE'))}, साथ में सबसे ज़्यादा आने वाले उत्तर और दोहराए गए प्रश्न।`,
      }
    : {
        title: `SSC GK Most Asked Topics and Answers: ${num(D.total, 'en')} Past Questions Analysed`,
        description: `Which General Awareness topics SSC asks most: ${num(D.total, 'en')} questions from ${D.paperCount} SSC CGL, CHSL, MTS and GD papers counted - static GK ${fmtPct(share('STATIC_GK'))}, art and culture ${fmtPct(share('ART_AND_CULTURE'))}, plus the most frequent answers and the questions SSC repeated.`,
      };
}

/** The data the check script asserts on (total and paper count printed on the page). */
export const GK_INSIGHTS_SUMMARY = { total: D.total, paperCount: D.paperCount, repeats: D.repeats.length };
